//! Veel's element schema: which kinds exist, what each holds, and how each value is written.
//!
//! The schema has two parts (`docs/design/compiler.md`). The editorial core is written by hand:
//! the kinds a Veel project is made of (`source`, `sequence`, `track`, `clip`, …), their
//! attributes and their value forms. The asset schema (every effect, transition and generator,
//! with its parameters) is generated by Annilay's `just schema` from Kdenlive's asset XML and
//! MLT's metadata and committed in Veel's `schema/` (task 1b-04); Veel never reads Kdenlive's
//! files itself.
//!
//! Until 1b-04, this crate holds only the phase 1a slice ([`slice`]): the slice's kinds, written
//! by hand from the spec's section 17, and its one effect, Kdenlive's Transform (`qtblend`), with
//! every parameter copied by hand from `data/effects/qtblend.xml` at Kdenlive's tag
//! [`KDENLIVE_TAG`], each citing the file, the tag and the line it was read from. 1b-04's gate
//! compares this copy with the generated schema.
//!
//! The schema is data: it says what a file may hold. Checking a file against it is `veel_check`
//! (task 1a-04).
//!
//! ```
//! use veel_schema::slice;
//!
//! let clip = slice::kind("clip").unwrap();
//! assert!(clip.attribute("at").unwrap().required);
//! let transform = slice::effect("qtblend").unwrap();
//! assert_eq!(transform.param("rotate-anchor").unwrap().kdenlive_name, "rotate_anchor");
//! ```

pub mod slice;

/// The Kdenlive release whose asset files the schema is read from: the tag Annilay imported
/// (task 0-04; Annilay's `kdenlive` branch, commit `a277c72`).
pub const KDENLIVE_TAG: &str = "v26.08.3";

/// A place in one of Kdenlive's files at a tag, which a schema entry was read from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cited {
    /// The file, from the root of Kdenlive's tree (`data/effects/qtblend.xml`).
    pub file: &'static str,
    /// The tag ([`KDENLIVE_TAG`]).
    pub tag: &'static str,
    /// The line, counting from 1.
    pub line: u32,
}

/// How a value is written: the forms the spec's section 17 gives each.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Value {
    /// A quoted string: a display name.
    Text,
    /// A quoted path, from the project's folder (Veelindy's RFC 0003 rules).
    Path,
    /// A content hash, `sha256:` and 64 lowercase hexadecimal digits (V10).
    Hash,
    /// An exact rate: a whole number (`25`) or a fraction (`30000/1001`).
    Rate,
    /// A frame size, `[width height]`, in whole pixels.
    Size,
    /// A source's length, at its own rate: `s`, `ms`, or a timecode counted from `00:00:00:00`.
    SourceLength,
    /// A sequence position: frames, `s` or `ms` from frame 0, or the sequence's timecode.
    Position,
    /// A clip's source range, `in..out` or `in..+length`, half-open (V21).
    SourceRange,
    /// A length in the sequence's frames: frames, `s` or `ms`.
    Length,
    /// A time in the clip, from its first frame: frames, `s` or `ms`.
    ClipTime,
    /// A timecode, `hh:mm:ss:ff`, written with colons.
    Timecode,
    /// A handle of the named kind.
    Handle(&'static str),
    /// One of these words.
    Word(&'static [&'static str]),
    /// `on` or `off`; the name alone means `on` (Null's form).
    OnOff,
    /// A rectangle `[x y w h]` in pixels of the sequence's frame, with an optional fifth item,
    /// the opacity (a number from 0 to 1, or a percent).
    Rect,
    /// A point `[x y]`, each a number (the stored scale) or a percent.
    Point,
    /// An angle: a number of degrees, bare or with `deg`.
    Angle,
    /// One of the parameter's [`Choice`] words.
    Choice,
    /// A value of the form of the parameter a `key` animates.
    Parameter,
}

/// A positional argument of a kind, after its handle.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Arg {
    /// What the argument is, for messages.
    pub name: &'static str,
    /// How it is written.
    pub value: Value,
    /// Whether every node of the kind must have it.
    pub required: bool,
}

/// An attribute: a name and one value, on its owner's line (`key=value`, or a bare keyword
/// attribute such as `at 0`) or as a child line (`rate 25`), which mean the same (spec, section
/// 4).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Attribute {
    /// The attribute's name, kebab-case.
    pub name: &'static str,
    /// How its value is written.
    pub value: Value,
    /// Whether every node of the kind must have it.
    pub required: bool,
    /// What it means when it is left out, if it may be.
    pub default: Option<&'static str>,
    /// What it is.
    pub doc: &'static str,
}

/// A kind of node.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Kind {
    /// The node's name, kebab-case.
    pub name: &'static str,
    /// What it is.
    pub doc: &'static str,
    /// What it is in Kdenlive.
    pub kdenlive: &'static str,
    /// Whether its first argument is its handle, which it must have.
    pub handle: bool,
    /// Its positional arguments after the handle, in order.
    pub args: &'static [Arg],
    /// Its attributes, in the order the canonical form prints them.
    pub attributes: &'static [Attribute],
    /// The kinds its block may hold. An effect's block holds its parameters instead
    /// ([`Effect`]), and a parameter's block holds `key` lines.
    pub children: &'static [&'static str],
    /// Whether it is written at the top of a file.
    pub top_level: bool,
}

impl Kind {
    /// The attribute named `name`.
    pub fn attribute(&self, name: &str) -> Option<&'static Attribute> {
        self.attributes.iter().find(|a| a.name == name)
    }
}

/// One `<effect>` element of an asset file: a file may hold several versions of one effect.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Element {
    /// Its `version` attribute as written, or `None` where it has none (Kdenlive reads that as
    /// version 0).
    pub version: Option<&'static str>,
    /// The line of its `<effect>` tag.
    pub line: u32,
}

/// Where a parameter is declared: one line in one element of the asset file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Declared {
    /// The element's `version` attribute, as in [`Element::version`].
    pub version: Option<&'static str>,
    /// The line of the `<parameter>` tag.
    pub line: u32,
}

/// A bound on a parameter, in the parameter's own unit and form, both ends inclusive: Scowr's
/// RFC 0001 form (G6). The words are the asset file's `min` and `max`. Whether a value outside
/// one is an error is task 1b-04's (spec, section 16), so the slice records them only.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Bound {
    /// The least value, as a word of the parameter's type.
    pub min: Option<&'static str>,
    /// The greatest value, as a word of the parameter's type.
    pub max: Option<&'static str>,
}

/// No bound at either end.
pub const UNBOUNDED: Bound = Bound {
    min: None,
    max: None,
};

/// One item of a list parameter: the Veel word, the value MLT stores, and Kdenlive's label.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Choice {
    /// The word Veel writes: the label in kebab-case.
    pub word: &'static str,
    /// The value MLT stores, from the asset file's `paramlist`.
    pub stored: &'static str,
    /// Kdenlive's label, from the asset file's `paramlistdisplay`, untranslated.
    pub display: &'static str,
}

/// One parameter of an effect.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Param {
    /// Veel's name: Kdenlive's in kebab-case (V18).
    pub name: &'static str,
    /// Kdenlive's and MLT's name, as the asset file spells it.
    pub kdenlive_name: &'static str,
    /// Kdenlive's label for it, the `<name>` inside the `<parameter>`, untranslated.
    pub label: &'static str,
    /// How its value is written.
    pub value: Value,
    /// Whether it takes a block of keyframes (its Kdenlive type is `animated…`).
    pub keyframes: bool,
    /// Its bound, from the asset file.
    pub bound: Bound,
    /// Its items, for a list parameter; empty otherwise.
    pub choices: &'static [Choice],
    /// The `<parameter>` tag's attributes, verbatim and in the file's order, from the element
    /// [`Param::read_from`] cites.
    pub xml: &'static [(&'static str, &'static str)],
    /// The line its attributes were read from: the element Kdenlive loads, or for a parameter
    /// that element lacks, the last element that declares it.
    pub read_from: Cited,
    /// Every element of the file that declares it.
    pub declared: &'static [Declared],
}

impl Param {
    /// The `<parameter>` attribute named `name`, as the file writes it.
    pub fn xml(&self, name: &str) -> Option<&'static str> {
        self.xml.iter().find(|(k, _)| *k == name).map(|(_, v)| *v)
    }

    /// Whether the element whose `version` attribute is `version` declares it.
    pub fn declared_in(&self, version: Option<&str>) -> bool {
        self.declared.iter().any(|d| d.version == version)
    }

    /// The choice whose word is `word`.
    pub fn choice(&self, word: &str) -> Option<&'static Choice> {
        self.choices.iter().find(|c| c.word == word)
    }
}

/// An effect: one asset file of Kdenlive's, all its elements and every parameter they declare.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Effect {
    /// Veel's selector: Kdenlive's asset id in kebab-case (V18).
    pub id: &'static str,
    /// Kdenlive's asset id (the `id` attribute).
    pub kdenlive_id: &'static str,
    /// The MLT service (the `tag` attribute).
    pub mlt_service: &'static str,
    /// Kdenlive's label, untranslated.
    pub label: &'static str,
    /// The file, from the root of Kdenlive's tree.
    pub file: &'static str,
    /// The tag it was read at ([`KDENLIVE_TAG`]).
    pub tag: &'static str,
    /// Every `<effect>` element of the file, in order.
    pub elements: &'static [Element],
    /// The `version` attribute of the element Kdenlive loads with the pinned MLT.
    pub loaded: Option<&'static str>,
    /// Every parameter any element declares, in the loaded element's order, then the rest.
    pub params: &'static [Param],
}

impl Effect {
    /// The parameter Veel names `name`.
    pub fn param(&self, name: &str) -> Option<&'static Param> {
        self.params.iter().find(|p| p.name == name)
    }

    /// The parameters of the element Kdenlive loads, which a Veel file may set.
    pub fn loaded_params(&self) -> impl Iterator<Item = &'static Param> + '_ {
        self.params.iter().filter(|p| p.declared_in(self.loaded))
    }
}

/// A keyframe type: Veel's `ease=` word, Kdenlive's `KeyframeType` name and MLT's
/// `mlt_keyframe_type` name.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Ease {
    /// The word Veel writes after `ease=`.
    pub word: &'static str,
    /// Kdenlive's name for it (`KeyframeType::KeyframeEnum`).
    pub kdenlive: &'static str,
    /// MLT's (`mlt_keyframe_type`), which Kdenlive's maps to.
    pub mlt: &'static str,
    /// Where Kdenlive declares it.
    pub cited: Cited,
}

/// Whether `word` is kebab-case: lowercase ASCII letters and digits in parts joined by single
/// hyphens, starting with a letter.
pub fn is_kebab(word: &str) -> bool {
    !word.is_empty()
        && word.starts_with(|c: char| c.is_ascii_lowercase())
        && word.split('-').all(|p| {
            !p.is_empty()
                && p.chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        })
}

